function offBeginSession(id,o,loc,when,part){const prev=offPreviousEnd(o);offArchiveUnfinishedSession(o);delete o.lastSession;o.loc=loc||'老地方';o.when=when||'现在';o.daypart=part||dayPartNow();o.started=true;o.session=uid();o.startedAt=Date.now();o.endedAt=0;o.previousEndedAt=prev;o.introSeen=false;o.summaryCursor=0;o.msgs=[];o.msgs.push({id:uid(),who:'日期',source:'system',text:offSessionMarker(o)});offlineFocusStart(id,o);if(typeof roleServerPushSyncSoon==='function')roleServerPushSyncSoon(id);}
